"""Tests for the daily rate price calculation."""

import pytest
from alloq_commons.models import DailyRate
from alloq_commons.services.daily_rate_pricing import (
    contribution_margin,
    price_rate,
    recommended_price,
    round_up_to_ten,
)


@pytest.mark.parametrize(
    ("value", "expected"),
    [(0, 0), (1, 10), (10, 10), (11, 20), (769, 770), (1000, 1000)],
)
def test_round_up_to_ten(value: int, expected: int) -> None:
    assert round_up_to_ten(value) == expected


@pytest.mark.parametrize(
    ("cost", "percent", "expected"),
    [
        (650, 35, 1000),  # 650 / 0.65 = 1000 exactly
        (500, 35, 770),  # 769.23 rounds up
        (505, 35, 780),  # 776.92 rounds up
        (500, 0, 500),
        (500, 50, 1000),
        (0, 35, 0),
    ],
)
def test_recommended_price_is_cost_over_cost_share_rounded_up(
    cost: int, percent: int, expected: int
) -> None:
    assert recommended_price(cost, percent) == expected


def test_contribution_margin_fills_the_gap_to_the_price() -> None:
    assert contribution_margin(500, 35) == 270
    assert contribution_margin(650, 35) == 350


def test_price_rate_sets_derived_values() -> None:
    rate = price_rate(DailyRate(id=1, role_name="Architekt", production_cost=650), 35)
    assert rate.recommended_price == 1000
    assert rate.contribution_margin == 350
    assert rate.production_cost == 650

"""Price calculation of daily rates.

The contribution margin is a share of the selling price: with 35 % margin the
production cost is the other 65 %, so price = cost / (1 - margin). The price is
rounded up to the next 10 EUR and the margin is what lies between cost and price.
"""

from alloq_commons.models import DailyRate

ROUNDING_STEP = 10


def round_up_to_ten(value: int) -> int:
    """Round a whole euro amount up to the next multiple of 10."""
    return -(-value // ROUNDING_STEP) * ROUNDING_STEP


def recommended_price(production_cost: int, margin_percent: int) -> int:
    """Selling price that yields the margin, rounded up to the next 10 EUR."""
    cost_share = 100 - margin_percent
    # Integer ceiling of cost * 100 / cost_share in steps of 10, without floats.
    steps = -(-production_cost * 100 // (cost_share * ROUNDING_STEP))
    return steps * ROUNDING_STEP


def contribution_margin(production_cost: int, margin_percent: int) -> int:
    """Euro amount between production cost and recommended price."""
    return recommended_price(production_cost, margin_percent) - production_cost


def price_rate(rate: DailyRate, margin_percent: int) -> DailyRate:
    """Copy of the rate with margin and recommended price filled in."""
    return rate.model_copy(
        update={
            "contribution_margin": contribution_margin(
                rate.production_cost, margin_percent
            ),
            "recommended_price": recommended_price(
                rate.production_cost, margin_percent
            ),
        }
    )

import logging
from collections.abc import AsyncGenerator
from typing import Any

import reflex as rx
from alloq_commons.entities import DailyRateEntity
from alloq_commons.entities.daily_rate import DEFAULT_CONTRIBUTION_MARGIN_PERCENT
from alloq_commons.models import (
    DailyRate,
    DailyRateCreate,
    DailyRateSettingsUpdate,
    Role,
)
from alloq_commons.models.daily_rate import (
    MAX_CONTRIBUTION_MARGIN_PERCENT,
    MAX_PRODUCTION_COST,
)
from alloq_commons.repositories import daily_rate_repo, role_repo
from alloq_commons.services.daily_rate_pricing import (
    contribution_margin,
    price_rate,
    recommended_price,
)
from pydantic import ValidationError
from sqlalchemy.exc import IntegrityError

from appkit_commons.database.session import get_asyncdb_session
from appkit_user.authentication.decorators import requires_admin

logger = logging.getLogger(__name__)

DUPLICATE_MESSAGE = "Für diese Rolle gibt es bereits einen Tagessatz."
INVALID_RATE_MESSAGE = (
    f"Rolle wählen und Herstellkosten zwischen 1 und {MAX_PRODUCTION_COST} € angeben."
)
INVALID_MARGIN_MESSAGE = (
    f"Der Deckungsbeitrag muss zwischen 0 und {MAX_CONTRIBUTION_MARGIN_PERCENT} % "
    "liegen."
)


def _whole_euros(value: float | str) -> int:
    """Number input value as whole number; empty or invalid input is 0."""
    try:
        return round(float(value))
    except TypeError, ValueError:
        return 0


class DailyRateState(rx.State):
    """State for the daily rates (Tagessätze) of the roles."""

    rates: rx.Field[list[DailyRate]] = rx.field(default_factory=list)
    roles: rx.Field[list[Role]] = rx.field(default_factory=list)
    margin_percent: rx.Field[int] = rx.field(DEFAULT_CONTRIBUTION_MARGIN_PERCENT)
    margin_draft: rx.Field[int] = rx.field(DEFAULT_CONTRIBUTION_MARGIN_PERCENT)
    is_loading: rx.Field[bool] = rx.field(False)
    search_filter: rx.Field[str] = rx.field("")

    modal_open: rx.Field[bool] = rx.field(False)
    editing_rate_id: rx.Field[int] = rx.field(0)
    draft_role_id: rx.Field[str] = rx.field("")
    draft_cost: rx.Field[int] = rx.field(0)
    form_version: rx.Field[int] = rx.field(0)

    @rx.var
    def priced_rates(self) -> list[DailyRate]:
        """Rates with derived prices, filtered by role name."""
        search = self.search_filter.lower()
        return [
            price_rate(rate, self.margin_percent)
            for rate in self.rates
            if search in rate.role_name.lower()
        ]

    @rx.var
    def role_options(self) -> list[dict[str, str]]:
        """Roles without a rate yet; the edited rate keeps its own role."""
        taken = {r.role_id for r in self.rates if r.id != self.editing_rate_id}
        return [
            {"value": str(role.id), "label": role.name}
            for role in self.roles
            if role.id not in taken
        ]

    @rx.var
    def is_editing(self) -> bool:
        """True while the modal edits an existing rate."""
        return self.editing_rate_id > 0

    @rx.var
    def draft_contribution_margin(self) -> int:
        """Preview of the margin for the cost entered in the modal."""
        return contribution_margin(self.draft_cost, self.margin_percent)

    @rx.var
    def draft_recommended_price(self) -> int:
        """Preview of the price for the cost entered in the modal."""
        return recommended_price(self.draft_cost, self.margin_percent)

    @rx.var
    def cost_share_percent(self) -> int:
        """Share of the production cost in the selling price."""
        return 100 - self.margin_percent

    @rx.var
    def margin_changed(self) -> bool:
        """True when the margin input differs from the stored margin."""
        return self.margin_draft != self.margin_percent

    @rx.event
    def set_search_filter(self, value: str) -> None:
        """Update the search filter."""
        self.search_filter = value

    @rx.event
    def set_margin_draft(self, value: float | str) -> None:
        """Keep the margin input until it is saved."""
        self.margin_draft = _whole_euros(value)

    @rx.event
    def set_draft_role(self, value: str | None) -> None:
        """Select the role of the rate in the modal."""
        self.draft_role_id = value or ""

    @rx.event
    def set_draft_cost(self, value: float | str) -> None:
        """Keep the production cost entered in the modal."""
        self.draft_cost = _whole_euros(value)

    @rx.event
    def open_add_modal(self) -> None:
        """Open the modal for a new rate."""
        self._open_modal(0, "", 0)

    @rx.event
    def edit_rate(self, rate_id: int) -> None:
        """Open the modal for an existing rate."""
        rate = next((r for r in self.rates if r.id == rate_id), None)
        if rate:
            self._open_modal(rate.id, str(rate.role_id), rate.production_cost)

    @rx.event
    def close_modal(self) -> None:
        """Close the rate modal."""
        self.modal_open = False
        self.editing_rate_id = 0

    def _open_modal(self, rate_id: int, role_id: str, cost: int) -> None:
        self.editing_rate_id = rate_id
        self.draft_role_id = role_id
        self.draft_cost = cost
        self.form_version += 1
        self.modal_open = True

    async def _load(self) -> None:
        async with get_asyncdb_session() as session:
            entities = await daily_rate_repo.find_all_by_role_name(session)
            roles = await role_repo.find_all_paginated(session)
            percent = await daily_rate_repo.get_margin_percent(session)
            self.rates = [DailyRate(**e.to_dict()) for e in entities]
            self.roles = [Role(**r.to_dict()) for r in roles]
        self.margin_percent = percent
        self.margin_draft = percent
        self.form_version += 1

    @rx.event
    @requires_admin
    async def load_daily_rates(self) -> AsyncGenerator[Any]:
        """Load rates, roles and the margin.

        The loading row only replaces the table on the first load; revisits
        refresh the existing rows in place to avoid a flicker.
        """
        if not self.rates:
            self.is_loading = True
            yield
        try:
            await self._load()
        except Exception:
            logger.exception("Failed to load daily rates")
            yield rx.toast.error(
                "Fehler beim Laden der Tagessätze.", position="top-right"
            )
        finally:
            self.is_loading = False

    @rx.event
    @requires_admin
    async def save_rate(self, _form_data: dict | None = None) -> AsyncGenerator[Any]:
        """Create or update the rate entered in the modal."""
        try:
            data = DailyRateCreate(
                role_id=int(self.draft_role_id or 0),
                production_cost=self.draft_cost,
            )
            found = True
            async with get_asyncdb_session() as session:
                if self.is_editing:
                    entity = await daily_rate_repo.find_by_id(
                        session, self.editing_rate_id
                    )
                    found = entity is not None
                    if entity:
                        entity.role_id = data.role_id
                        entity.production_cost = data.production_cost
                        await daily_rate_repo.update(session, entity)
                else:
                    await daily_rate_repo.create(
                        session,
                        DailyRateEntity(
                            role_id=data.role_id,
                            production_cost=data.production_cost,
                        ),
                    )
        except ValidationError:
            yield rx.toast.error(INVALID_RATE_MESSAGE, position="top-right")
            return
        except IntegrityError:
            yield rx.toast.error(DUPLICATE_MESSAGE, position="top-right")
            return
        except Exception:
            logger.exception("Failed to save daily rate")
            yield rx.toast.error(
                "Fehler beim Speichern des Tagessatzes.", position="top-right"
            )
            return
        if not found:
            yield rx.toast.error("Tagessatz nicht gefunden.", position="top-right")
            return
        await self._load()
        self.close_modal()
        yield rx.toast.info("Tagessatz wurde gespeichert.", position="top-right")

    @rx.event
    @requires_admin
    async def delete_rate(self, rate_id: int) -> AsyncGenerator[Any]:
        """Delete a rate by ID."""
        try:
            async with get_asyncdb_session() as session:
                deleted = await daily_rate_repo.delete_by_id(session, rate_id)
        except Exception:
            logger.exception("Failed to delete daily rate %d", rate_id)
            yield rx.toast.error(
                "Fehler beim Löschen des Tagessatzes.", position="top-right"
            )
            return
        if not deleted:
            yield rx.toast.error("Tagessatz nicht gefunden.", position="top-right")
            return
        await self._load()
        yield rx.toast.info("Tagessatz wurde gelöscht.", position="top-right")

    @rx.event
    @requires_admin
    async def save_margin(self) -> AsyncGenerator[Any]:
        """Store the contribution margin used for all roles."""
        try:
            data = DailyRateSettingsUpdate(contribution_margin_percent=self.margin_draft)
            async with get_asyncdb_session() as session:
                await daily_rate_repo.save_margin_percent(
                    session, data.contribution_margin_percent
                )
        except ValidationError:
            yield rx.toast.error(INVALID_MARGIN_MESSAGE, position="top-right")
            return
        except Exception:
            logger.exception("Failed to save contribution margin")
            yield rx.toast.error(
                "Fehler beim Speichern des Deckungsbeitrags.", position="top-right"
            )
            return
        self.margin_percent = data.contribution_margin_percent
        yield rx.toast.info(
            f"Deckungsbeitrag auf {self.margin_percent} % gesetzt.",
            position="top-right",
        )

